                'country' => $registeredUser['country'] ?? 'Kenya',
                'created_at' => $registeredUser['created_at'] ?? date('Y-m-d H:i:s'),
            ]);
            $success = 'Account created successfully.';
            header('Location: dashboard.php');
            exit;
        }
    }
}
