$message = '';
$messageType = '';

// Check if any admin exists
$users = getUsers();
$adminExists = false;
foreach ($users as $user) {
    if ($user['role'] === 'admin') {
        $adminExists = true;
        break;
    }
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $adminKey = trim($_POST['admin_key'] ?? '');
    $fullName = trim($_POST['full_name'] ?? '');
    $email = trim($_POST['email'] ?? '');
    $password = trim($_POST['password'] ?? '');
    $confirmPassword = trim($_POST['confirm_password'] ?? '');

    // Simple admin key for first admin setup
    $VALID_ADMIN_KEY = 'AQUA_ADMIN_2024';

    if ($adminKey !== $VALID_ADMIN_KEY) {
        $message = '❌ Invalid admin key.';
        $messageType = 'error';
    } elseif ($password !== $confirmPassword) {
        $message = '❌ Passwords do not match.';
        $messageType = 'error';
    } elseif (empty($fullName) || empty($email) || empty($password)) {
        $message = '❌ Please fill in all required fields.';
        $messageType = 'error';
    } else {
        // Check if email already exists
        $users = getUsers();
        $emailExists = false;
        foreach ($users as $user) {
            if (strtolower($user['email']) === strtolower($email)) {
                $emailExists = true;
                break;
            }
        }

        if ($emailExists) {
            $message = '❌ An account with this email already exists.';
            $messageType = 'error';
        } else {
            // Create admin account
            $newAdmin = [
                'id' => count($users) > 0 ? max(array_column($users, 'id')) + 1 : 1,
                'name' => $fullName,
                'email' => strtolower($email),
                'phone' => '',
                'password' => password_hash($password, PASSWORD_DEFAULT),
                'role' => 'admin',
                'balance' => 0,
                'invested' => 0,
                'profit' => 0,
                'available_withdrawal' => 0,
                'country' => 'Kenya',
                'created_at' => date('Y-m-d H:i:s')
            ];

            $users[] = $newAdmin;
            saveUsers($users);

            $message = '✅ Admin account created successfully! You can now <a href="admin-login.php">login as admin</a>.';
            $messageType = 'success';
        }
    }
}
?>
