{
    $transactions = getAllTransactions();
    foreach ($transactions as &$transaction) {
        if ((int) $transaction['id'] === $transactionId) {
            $transaction['status'] = $status;
            if ($note !== '') {
                $transaction['note'] = $note;
            }
            saveTransactions($transactions);
            return true;
        }
    }
    return false;
